77      }
78    }

You can also write custom messages within a tool:

 1export const planActivities = createTool({
 2  execute: async ({ mastra, context, writer }) => {
 3    const agent = mastra!.getAgent("weatherAgent");
 4    const prompt = "some prompt";
 5    const response = agent.streamVNext([
 6      {
 7        role: "user",
 8        content: prompt,
 9      },
10    ]);
11
12    await response.pipeTo(writer);
13
14    // or simply call writer.write({})
15
16    return {
17      activities: await response.text,
18    };
19  },
20});

This will pipe the agent output into the stream:

 1{
 2  type: 'tool-output',
 3  runId: 'string',
 4  from: 'USER',
 5  payload: {
 6    output: // nested output of the agent,
 7    toolCallId: string,
 8    toolName: string
 9  }
10}

To get the total usage at the end, simply call await stream.usage:

 1console.log("total usage", await stream.usage);
Workflows

You can stream a workflow using the same streamVNext function. This feature enables real-time tracking of every step the workflow performs, providing you with a detailed, step-by-step account of its operations. You can also integrate custom messaging within various steps or incorporate agents into the process. After the streaming session, you'll receive the total token usage across all involved primitives.

 1const result = run.streamVNext({
 2  inputData: { location: "New York" },
 3});
 4
 5for await (const chunk of result) {
 6  console.log({ chunk });
 7}

